  --color-sidebar-border: var(--sidebar-border);
  --color-sidebar-ring: var(--sidebar-ring);
}

:root {
  --radius: 0.75rem;
  --background: oklch(0.98 0.008 80);
  --foreground: oklch(0.22 0.01 260);
  --card: oklch(1.0 0.0 0);
  --card-foreground: oklch(0.22 0.01 260);
  --popover: oklch(1.0 0.0 0);
  --popover-foreground: oklch(0.22 0.01 260);
  --primary: oklch(0.55 0.10 155);
  --primary-foreground: oklch(0.99 0.0 0);
  --secondary: oklch(0.94 0.04 155);
  --secondary-foreground: oklch(0.30 0.07 155);
  --muted: oklch(0.96 0.006 80);
  --muted-foreground: oklch(0.52 0.01 260);
  --accent: oklch(0.94 0.04 155);
  --accent-foreground: oklch(0.30 0.07 155);
  --destructive: oklch(0.55 0.18 25);
  --border: oklch(0.90 0.008 80);
  --input: oklch(0.90 0.008 80);
  --ring: oklch(0.55 0.10 155);
  --chart-1: oklch(0.55 0.10 155);
  --chart-2: oklch(0.62 0.12 155);
  --chart-3: oklch(0.70 0.08 155);
  --chart-4: oklch(0.80 0.06 155);
  --chart-5: oklch(0.45 0.10 155);
  --sidebar: oklch(0.20 0.025 155);
  --sidebar-foreground: oklch(0.93 0.01 80);
  --sidebar-primary: oklch(0.55 0.10 155);
  --sidebar-primary-foreground: oklch(0.99 0.0 0);
  --sidebar-accent: oklch(0.27 0.03 155);
  --sidebar-accent-foreground: oklch(0.93 0.01 80);
  --sidebar-border: oklch(0.27 0.025 155);
  --sidebar-ring: oklch(0.55 0.10 155);

  /* Custom tokens */
  --gradient-primary: linear-gradient(135deg, oklch(0.55 0.10 155), oklch(0.62 0.12 155));
  --gradient-subtle: linear-gradient(160deg, oklch(0.98 0.008 80), oklch(0.95 0.015 155));
  --shadow-elegant: 0 4px 20px -4px oklch(0.22 0.01 260 / 0.12);
  --shadow-card: 0 1px 4px oklch(0.22 0.01 260 / 0.08);
  --color-success: oklch(0.62 0.12 155);
  --color-success-bg: oklch(0.94 0.04 155);
}

.dark {
  --background: oklch(0.145 0 0);
  --foreground: oklch(0.985 0 0);
  --card: oklch(0.205 0 0);
  --card-foreground: oklch(0.985 0 0);
  --popover: oklch(0.205 0 0);
  --popover-foreground: oklch(0.985 0 0);
  --primary: oklch(0.922 0 0);
  --primary-foreground: oklch(0.205 0 0);
  --secondary: oklch(0.269 0 0);
  --secondary-foreground: oklch(0.985 0 0);
  --muted: oklch(0.269 0 0);
  --muted-foreground: oklch(0.708 0 0);
  --accent: oklch(0.269 0 0);
  --accent-foreground: oklch(0.985 0 0);
  --destructive: oklch(0.704 0.191 22.216);
  --border: oklch(1 0 0 / 10%);
  --input: oklch(1 0 0 / 15%);
  --ring: oklch(0.556 0 0);
  --chart-1: oklch(0.488 0.243 264.376);
  --chart-2: oklch(0.696 0.17 162.48);
  --chart-3: oklch(0.769 0.188 70.08);
  --chart-4: oklch(0.627 0.265 303.9);
  --chart-5: oklch(0.645 0.246 16.439);
  --sidebar: oklch(0.205 0 0);
  --sidebar-foreground: oklch(0.985 0 0);
  --sidebar-primary: oklch(0.488 0.243 264.376);
  --sidebar-primary-foreground: oklch(0.985 0 0);
  --sidebar-accent: oklch(0.269 0 0);
  --sidebar-accent-foreground: oklch(0.985 0 0);
  --sidebar-border: oklch(1 0 0 / 10%);
  --sidebar-ring: oklch(0.556 0 0);
}

@layer base {
  * {
    @apply border-border outline-ring/50;
  }
  body {
    @apply bg-background text-foreground;
  }
}

input.content:
import { useEffect, useState, useMemo, useCallback } from 'react';
import { format, parseISO, subDays, isToday } from 'date-fns';
import { de } from 'date-fns/locale';
import { Check, Plus, Clock, Target, Calendar, TrendingUp, Pencil, Trash2, X, AlertCircle } from 'lucide-react';
import { BarChart, Bar, XAxis, ResponsiveContainer, Tooltip } from 'recharts';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Skeleton } from '@/components/ui/skeleton';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { LivingAppsService, extractRecordId, createRecordUrl } from '@/services/livingAppsService';
import { APP_IDS } from '@/types/app';
import type { GewohnheitenVerwaltung, TaeglicheEintraege } from '@/types/app';

// --- Types ---
interface EntryDialogState {
  open: boolean;
  mode: 'create' | 'edit';
  entryId?: string;
  habitId?: string;
  ausgefuehrt: boolean;
  investierte_zeit_minuten: string;
  datum: string;
}

// --- Circular Progress Ring Component ---
function ProgressRing({
  percent,
  size = 52,
  stroke = 5,
  done = false,
}: {
  percent: number;
  size?: number;
  stroke?: number;
  done?: boolean;
}) {
  const radius = (size - stroke) / 2;
  const circumference = 2 * Math.PI * radius;
  const filled = Math.min(percent, 100);
  const offset = circumference - (filled / 100) * circumference;

  return (
    <svg width={size} height={size} style={{ transform: 'rotate(-90deg)' }}>
      <circle
        cx={size / 2}
        cy={size / 2}
        r={radius}
        fill="none"
        stroke="var(--border)"
        strokeWidth={stroke}
      />
      <circle
        cx={size / 2}
        cy={size / 2}
        r={radius}
        fill="none"
        stroke={done ? 'var(--primary)' : 'oklch(0.70 0.08 155)'}
        strokeWidth={stroke}
        strokeLinecap="round"
        strokeDasharray={circumference}
        strokeDashoffset={offset}
        style={{ transition: 'stroke-dashoffset 0.5s ease' }}
      />
    </svg>
  );
}

// --- Greeting based on time ---
function getGreeting(): string {
  const hour = new Date().getHours();
  if (hour < 12) return 'Guten Morgen';
  if (hour < 18) return 'Guten Tag';
  return 'Guten Abend';
}

// --- Main Dashboard ---
export default function DashboardOverview() {
  const [habits, setHabits] = useState<GewohnheitenVerwaltung[]>([]);
  const [entries, setEntries] = useState<TaeglicheEintraege[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [saving, setSaving] = useState(false);
  const [deleting, setDeleting] = useState<string | null>(null);

  const todayStr = format(new Date(), 'yyyy-MM-dd');

  const [dialog, setDialog] = useState<EntryDialogState>({
    open: false,
    mode: 'create',
    ausgefuehrt: true,
    investierte_zeit_minuten: '',
    datum: todayStr,
  });

  // --- Load data ---
  const loadData = useCallback(async () => {
    try {
      setError(null);
      const [h, e] = await Promise.all([
        LivingAppsService.getGewohnheitenVerwaltung(),
        LivingAppsService.getTaeglicheEintraege(),
      ]);
      setHabits(h);
      setEntries(e);
    } catch (err) {
      setError('Daten konnten nicht geladen werden. Bitte erneut versuchen.');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    loadData();
  }, [loadData]);

  // --- Derived data ---
  // Map: habitId -> today's entry (if exists)
  const todayEntryByHabit = useMemo(() => {
    const map = new Map<string, TaeglicheEintraege>();
    entries.forEach((e) => {
      if (!e.fields.datum) return;
      const entryDate = e.fields.datum.split('T')[0];
      if (entryDate !== todayStr) return;
      const hId = extractRecordId(e.fields.gewohnheit);
      if (!hId) return;
      // If multiple entries today, prefer ausgefuehrt ones
      const existing = map.get(hId);
      if (!existing || e.fields.ausgefuehrt) {
        map.set(hId, e);
      }
    });
    return map;
  }, [entries, todayStr]);

  // Today's completed count
  const todayDoneCount = useMemo(() => {
    let count = 0;
    habits.forEach((h) => {
      const entry = todayEntryByHabit.get(h.record_id);
      if (entry?.fields.ausgefuehrt) count++;
    });
    return count;
  }, [habits, todayEntryByHabit]);

  // 7-day chart data
  const chartData = useMemo(() => {
    return Array.from({ length: 7 }, (_, i) => {
      const date = subDays(new Date(), 6 - i);
      const dateStr = format(date, 'yyyy-MM-dd');
      const label = format(date, 'EEE', { locale: de }).slice(0, 2);
      const count = entries.filter((e) => {
        const d = e.fields.datum?.split('T')[0];
        return d === dateStr && e.fields.ausgefuehrt === true;
      }).length;
      return { label, count, isToday: isToday(date) };
    });
  }, [entries]);

  // Recent entries (last 5)
  const recentEntries = useMemo(() => {
    const habitMap = new Map(habits.map((h) => [h.record_id, h]));
    return [...entries]
      .sort((a, b) => b.createdat.localeCompare(a.createdat))
      .slice(0, 5)
      .map((e) => {
        const hId = extractRecordId(e.fields.gewohnheit);
        const habit = hId ? habitMap.get(hId) : undefined;
        return { ...e, habitName: habit?.fields.gewohnheit_name ?? '—' };
      });
  }, [entries, habits]);

  // --- Toggle habit done/undone ---
  const handleToggleHabit = useCallback(
    async (habit: GewohnheitenVerwaltung) => {
      const existing = todayEntryByHabit.get(habit.record_id);
      if (existing) {
        // Already has entry — toggle ausgefuehrt
        setSaving(true);
        try {
          await LivingAppsService.updateTaeglicheEintraegeEntry(existing.record_id, {
            ausgefuehrt: !existing.fields.ausgefuehrt,
          });
          setEntries((prev) =>
            prev.map((e) =>
              e.record_id === existing.record_id
                ? { ...e, fields: { ...e.fields, ausgefuehrt: !existing.fields.ausgefuehrt } }
                : e
            )
          );
        } catch {
          setError('Eintrag konnte nicht aktualisiert werden.');
        } finally {
          setSaving(false);
        }
      } else {
        // No entry yet — create one marked done
        setSaving(true);
        try {
          const created = await LivingAppsService.createTaeglicheEintraegeEntry({
            datum: todayStr,
            gewohnheit: createRecordUrl(APP_IDS.GEWOHNHEITEN_VERWALTUNG, habit.record_id),
            ausgefuehrt: true,
            investierte_zeit_minuten: habit.fields.zielzeit_minuten ?? 0,
          });
          if (created?.record_id) {
            setEntries((prev) => [...prev, { record_id: created.record_id, createdat: created.createdat ?? new Date().toISOString(), updatedat: null, fields: created.fields ?? { datum: todayStr, gewohnheit: createRecordUrl(APP_IDS.GEWOHNHEITEN_VERWALTUNG, habit.record_id), ausgefuehrt: true, investierte_zeit_minuten: habit.fields.zielzeit_minuten ?? 0 } }]);
          } else {
            await loadData();
          }
        } catch {
          setError('Eintrag konnte nicht gespeichert werden.');
        } finally {
          setSaving(false);
        }
      }
    },
    [todayEntryByHabit, todayStr, loadData]
  );

  // --- Open edit dialog for a habit's today entry ---
  const handleEditEntry = useCallback(
    (habit: GewohnheitenVerwaltung) => {
      const existing = todayEntryByHabit.get(habit.record_id);
      if (existing) {
        setDialog({
          open: true,
          mode: 'edit',
          entryId: existing.record_id,
          habitId: habit.record_id,
          ausgefuehrt: existing.fields.ausgefuehrt ?? false,
          investierte_zeit_minuten: String(existing.fields.investierte_zeit_minuten ?? ''),
          datum: existing.fields.datum?.split('T')[0] ?? todayStr,
        });
      }
    },
    [todayEntryByHabit, todayStr]
  );

  // --- Open create dialog ---
  const handleOpenCreateDialog = useCallback((habitId?: string) => {
    setDialog({
      open: true,
      mode: 'create',
      habitId: habitId,
      ausgefuehrt: true,
      investierte_zeit_minuten: '',
      datum: todayStr,
    });
  }, [todayStr]);

  // --- Save dialog ---
  const handleSaveDialog = useCallback(async () => {
    if (!dialog.habitId) return;
    setSaving(true);
    try {
      const fields = {
        datum: dialog.datum,
        gewohnheit: createRecordUrl(APP_IDS.GEWOHNHEITEN_VERWALTUNG, dialog.habitId),
        ausgefuehrt: dialog.ausgefuehrt,
        investierte_zeit_minuten: dialog.investierte_zeit_minuten
          ? Number(dialog.investierte_zeit_minuten)
          : undefined,
      };
      if (dialog.mode === 'edit' && dialog.entryId) {
        await LivingAppsService.updateTaeglicheEintraegeEntry(dialog.entryId, fields);
      } else {
        await LivingAppsService.createTaeglicheEintraegeEntry(fields);
      }
      await loadData();
      setDialog((d) => ({ ...d, open: false }));
    } catch {
      setError('Eintrag konnte nicht gespeichert werden.');
    } finally {
      setSaving(false);
    }
  }, [dialog, loadData]);

  // --- Delete entry ---
  const handleDeleteEntry = useCallback(
    async (entryId: string) => {
      setDeleting(entryId);
      try {
        await LivingAppsService.deleteTaeglicheEintraegeEntry(entryId);
        setEntries((prev) => prev.filter((e) => e.record_id !== entryId));
        setDialog((d) => ({ ...d, open: false }));
      } catch {
        setError('Eintrag konnte nicht gelöscht werden.');
      } finally {
        setDeleting(null);
      }
    },
    []
  );

  // --- Render ---
  const todayFormatted = format(new Date(), 'EEEE, d. MMMM', { locale: de });

  if (loading) {
    return (
      <div className="space-y-6 animate-pulse">
        <div>
          <Skeleton className="h-8 w-64 mb-2" />
          <Skeleton className="h-5 w-48" />
        </div>
        <div className="grid grid-cols-3 gap-3">
          {[1, 2, 3].map((i) => <Skeleton key={i} className="h-16 rounded-xl" />)}
        </div>
        <div className="lg:grid lg:grid-cols-5 lg:gap-6 space-y-4 lg:space-y-0">
          <div className="lg:col-span-3 space-y-3">
            {[1, 2, 3].map((i) => <Skeleton key={i} className="h-24 rounded-2xl" />)}
          </div>
          <div className="lg:col-span-2 space-y-4">
            <Skeleton className="h-32 rounded-xl" />
            <Skeleton className="h-48 rounded-xl" />
          </div>
        </div>
      </div>
    );
  }

  if (error && habits.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center py-20 gap-4">
        <div className="flex items-center gap-2 text-destructive">
          <AlertCircle size={20} />
          <span className="font-semibold">{error}</span>
        </div>
        <Button variant="outline" onClick={loadData}>
          Erneut versuchen
        </Button>
      </div>
    );
  }

  return (
    <div className="space-y-6 pb-24 lg:pb-0">
      {/* Error toast */}
      {error && habits.length > 0 && (
        <div className="flex items-center gap-3 p-3 bg-destructive/10 text-destructive rounded-xl border border-destructive/20 text-sm">
          <AlertCircle size={16} />
          <span>{error}</span>
          <button onClick={() => setError(null)} className="ml-auto">
            <X size={14} />
          </button>
        </div>
      )}

      {/* Header */}
      <div className="flex items-start justify-between">
        <div>
          <p className="text-sm font-600 text-muted-foreground tracking-wide uppercase">{getGreeting()}</p>
          <h1 className="text-2xl lg:text-3xl font-800 tracking-tight text-foreground capitalize">{todayFormatted}</h1>
        </div>
        {/* Desktop primary action */}
        <Button
          onClick={() => handleOpenCreateDialog()}
          className="hidden lg:flex items-center gap-2 shadow-sm"
          disabled={saving}
        >
          <Plus size={16} />
          Eintrag hinzufügen
        </Button>
      </div>

      {/* KPI Pills — horizontal scroll on mobile */}
      <div className="flex gap-3 overflow-x-auto pb-1 lg:pb-0 scrollbar-hide">
        {[
          {
            icon: <Target size={14} />,
            label: 'Heute erledigt',
            value: `${todayDoneCount} / ${habits.length}`,
            accent: todayDoneCount === habits.length && habits.length > 0,
          },
          {
            icon: <Calendar size={14} />,
            label: 'Gewohnheiten',
            value: habits.length,
            accent: false,
          },
          {
            icon: <TrendingUp size={14} />,
            label: 'Einträge gesamt',
            value: entries.length,
            accent: false,
          },
        ].map((kpi, i) => (
          <div
            key={i}
            className={`flex-shrink-0 flex items-center gap-2.5 px-4 py-2.5 rounded-full border text-sm font-600 whitespace-nowrap transition-colors ${
              kpi.accent
                ? 'bg-primary text-primary-foreground border-primary'
                : 'bg-card text-foreground border-border'
            }`}
            style={{ boxShadow: 'var(--shadow-card)' }}
          >
            <span className={kpi.accent ? 'text-primary-foreground/80' : 'text-muted-foreground'}>
              {kpi.icon}
            </span>
            <span>{kpi.label}:</span>
            <span className="font-800">{kpi.value}</span>
          </div>
        ))}
      </div>

      {/* Main 2-column layout */}
      <div className="lg:grid lg:grid-cols-5 lg:gap-6 space-y-6 lg:space-y-0">

        {/* LEFT — Daily Habit Board */}
        <div className="lg:col-span-3 space-y-3">
          <div className="flex items-center justify-between">
            <h2 className="text-lg font-700 text-foreground">Heute</h2>
            <Badge variant="secondary" className="text-xs font-600">
              {todayDoneCount} / {habits.length} erledigt
            </Badge>
          </div>

          {habits.length === 0 ? (
            <div className="flex flex-col items-center justify-center py-16 gap-3 bg-card rounded-2xl border border-border">
              <div className="w-12 h-12 rounded-full bg-accent flex items-center justify-center">
                <Target size={22} className="text-primary" />
              </div>
              <p className="font-600 text-foreground">Noch keine Gewohnheiten</p>
              <p className="text-sm text-muted-foreground text-center max-w-xs">
                Erstelle deine erste Gewohnheit unter "Gewohnheiten-Verwaltung"
              </p>
            </div>
          ) : (
            habits.map((habit, idx) => {
              const entry = todayEntryByHabit.get(habit.record_id);
              const done = entry?.fields.ausgefuehrt === true;
              const timeInvested = entry?.fields.investierte_zeit_minuten ?? 0;
              const timeGoal = habit.fields.zielzeit_minuten ?? 0;
              const percent = timeGoal > 0 ? Math.round((timeInvested / timeGoal) * 100) : done ? 100 : 0;

              return (
                <div
                  key={habit.record_id}
                  className={`
                    group relative flex items-center gap-4 p-4 rounded-2xl border bg-card transition-all duration-200
                    hover:shadow-md
                    ${done ? 'border-l-4 border-l-primary' : 'border-border'}
                  `}
                  style={{
                    boxShadow: 'var(--shadow-card)',
                    animationDelay: `${idx * 50}ms`,
                  }}
                >
                  {/* Toggle button */}
                  <button
                    onClick={() => handleToggleHabit(habit)}
                    disabled={saving}
                    className={`
                      flex-shrink-0 w-9 h-9 rounded-full border-2 flex items-center justify-center transition-all duration-200
                      ${done
                        ? 'bg-primary border-primary text-primary-foreground'
                        : 'border-border hover:border-primary bg-transparent text-transparent hover:text-primary/40'
                      }
                    `}
                    aria-label={done ? 'Als unerledigt markieren' : 'Als erledigt markieren'}
                  >
                    <Check size={16} strokeWidth={3} />
                  </button>

                  {/* Habit info */}
                  <div className="flex-1 min-w-0">
                    <p className={`font-700 text-base truncate ${done ? 'text-muted-foreground line-through' : 'text-foreground'}`}>
                      {habit.fields.gewohnheit_name ?? 'Unbenannte Gewohnheit'}
                    </p>
                    {habit.fields.beschreibung && (
                      <p className="text-sm text-muted-foreground truncate mt-0.5">
                        {habit.fields.beschreibung}
                      </p>
                    )}
                    <div className="flex items-center gap-2 mt-1.5 flex-wrap">
                      {timeGoal > 0 && (
                        <span className="inline-flex items-center gap-1 text-xs text-muted-foreground">
                          <Clock size={11} />
                          {timeGoal} Min Ziel
                        </span>
                      )}
                      {done && timeInvested > 0 && (
                        <Badge
                          variant="secondary"
                          className="text-xs font-600 bg-accent text-accent-foreground py-0 px-2 h-5"
                        >
                          {timeInvested} Min investiert
                        </Badge>
                      )}
                    </div>
                  </div>

                  {/* Progress ring */}
                  <div className="flex-shrink-0 flex flex-col items-center gap-1">
                    <ProgressRing percent={percent} size={48} stroke={5} done={done} />
                    <span className="text-xs text-muted-foreground font-600">{percent}%</span>
                  </div>

                  {/* Edit button (appears on hover when done) */}
                  {done && entry && (
                    <button
                      onClick={() => handleEditEntry(habit)}
                      className="absolute top-2 right-2 opacity-0 group-hover:opacity-100 transition-opacity p-1.5 rounded-lg hover:bg-muted text-muted-foreground"
                      aria-label="Eintrag bearbeiten"
                    >
                      <Pencil size={13} />
                    </button>
                  )}
                </div>
              );
            })
          )}
        </div>

        {/* RIGHT — Analytics */}
        <div className="lg:col-span-2 space-y-4">
          {/* Desktop quick add button */}
          <Button
            onClick={() => handleOpenCreateDialog()}
            className="hidden lg:flex w-full items-center gap-2 shadow-sm"
            disabled={saving}
          >
            <Plus size={16} />
            Eintrag hinzufügen
          </Button>

          {/* 7-day bar chart */}
          <div className="bg-card rounded-2xl border border-border p-4" style={{ boxShadow: 'var(--shadow-card)' }}>
            <div className="flex items-center gap-2 mb-3">
              <TrendingUp size={16} className="text-primary" />
              <h3 className="font-700 text-sm text-foreground">Letzte 7 Tage</h3>
            </div>
            <div className="h-[140px]">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart data={chartData} barCategoryGap="30%">
                  <XAxis
                    dataKey="label"
                    tick={{ fontSize: 11, fill: 'var(--muted-foreground)', fontFamily: 'Nunito Sans' }}
                    axisLine={false}
                    tickLine={false}
                  />
                  <Tooltip
                    cursor={{ fill: 'var(--muted)', radius: 6 }}
                    contentStyle={{
                      backgroundColor: 'var(--card)',
                      border: '1px solid var(--border)',
                      borderRadius: '8px',
                      fontSize: '12px',
                      fontFamily: 'Nunito Sans',
                      color: 'var(--foreground)',
                    }}
                    formatter={(value: number) => [`${value} erledigt`, '']}
                    labelFormatter={(label) => label}
                  />
                  <Bar
                    dataKey="count"
                    radius={[4, 4, 0, 0]}
                    fill="var(--primary)"
                  />
                </BarChart>
              </ResponsiveContainer>
            </div>
          </div>

          {/* Recent entries */}
          <div className="bg-card rounded-2xl border border-border p-4" style={{ boxShadow: 'var(--shadow-card)' }}>
            <div className="flex items-center gap-2 mb-3">
              <Calendar size={16} className="text-primary" />
              <h3 className="font-700 text-sm text-foreground">Letzte Einträge</h3>
            </div>
            {recentEntries.length === 0 ? (
              <p className="text-sm text-muted-foreground py-4 text-center">Noch keine Einträge</p>
            ) : (
              <div className="space-y-2">
                {recentEntries.map((entry) => (
                  <div
                    key={entry.record_id}
                    className="flex items-center gap-3 py-2 px-1 rounded-lg hover:bg-muted transition-colors"
                  >
                    <div
                      className={`w-2 h-2 rounded-full flex-shrink-0 ${
                        entry.fields.ausgefuehrt ? 'bg-primary' : 'bg-border'
                      }`}
                    />
                    <div className="flex-1 min-w-0">
                      <p className="text-sm font-600 text-foreground truncate">{entry.habitName}</p>
                      <p className="text-xs text-muted-foreground">
                        {entry.fields.datum
                          ? format(parseISO(entry.fields.datum), 'dd.MM.yyyy', { locale: de })
                          : '—'}
                        {entry.fields.investierte_zeit_minuten ? ` · ${entry.fields.investierte_zeit_minuten} Min` : ''}
                      </p>
                    </div>
                    <Badge
                      variant={entry.fields.ausgefuehrt ? 'default' : 'secondary'}
                      className={`text-xs flex-shrink-0 ${
                        entry.fields.ausgefuehrt
                          ? 'bg-accent text-accent-foreground'
                          : 'bg-muted text-muted-foreground'
                      }`}
                    >
                      {entry.fields.ausgefuehrt ? '✓' : '—'}
                    </Badge>
                  </div>
                ))}
              </div>
            )}
          </div>
        </div>
      </div>

      {/* Mobile FAB */}
      <button
        onClick={() => handleOpenCreateDialog()}
        disabled={saving}
        className="lg:hidden fixed bottom-6 right-6 z-50 flex items-center gap-2 bg-primary text-primary-foreground px-4 py-3.5 rounded-full shadow-lg hover:shadow-xl active:scale-95 transition-all font-700 text-sm"
        style={{ boxShadow: '0 8px 24px -4px oklch(0.55 0.10 155 / 0.4)' }}
      >
        <Plus size={18} />
        Eintrag
      </button>

      {/* Entry Dialog */}
      <Dialog open={dialog.open} onOpenChange={(open) => setDialog((d) => ({ ...d, open }))}>
        <DialogContent className="sm:max-w-md">
          <DialogHeader>
            <DialogTitle className="font-700">
              {dialog.mode === 'edit' ? 'Eintrag bearbeiten' : 'Eintrag hinzufügen'}
            </DialogTitle>
          </DialogHeader>
          <div className="space-y-4 pt-2">
            {/* Habit select */}
            <div className="space-y-1.5">
              <Label htmlFor="habit-select" className="text-sm font-600">Gewohnheit</Label>
              <Select
                value={dialog.habitId ?? ''}
                onValueChange={(v) => setDialog((d) => ({ ...d, habitId: v }))}
              >
                <SelectTrigger id="habit-select">
                  <SelectValue placeholder="Gewohnheit wählen…" />
                </SelectTrigger>
                <SelectContent>
                  {habits.map((h) => (
                    <SelectItem key={h.record_id} value={h.record_id}>
                      {h.fields.gewohnheit_name ?? 'Unbenannt'}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            {/* Date */}
            <div className="space-y-1.5">
              <Label htmlFor="entry-date" className="text-sm font-600">Datum</Label>
              <Input
                id="entry-date"
                type="date"
                value={dialog.datum}
                onChange={(e) => setDialog((d) => ({ ...d, datum: e.target.value }))}
              />
            </div>

            {/* Time invested */}
            <div className="space-y-1.5">
              <Label htmlFor="entry-time" className="text-sm font-600">Investierte Zeit (Minuten)</Label>
              <Input
                id="entry-time"
                type="number"
                min="0"
                placeholder="z.B. 30"
                value={dialog.investierte_zeit_minuten}
                onChange={(e) => setDialog((d) => ({ ...d, investierte_zeit_minuten: e.target.value }))}
              />
            </div>

            {/* Ausgefuehrt toggle */}
            <div className="flex items-center gap-3">
              <button
                type="button"
                onClick={() => setDialog((d) => ({ ...d, ausgefuehrt: !d.ausgefuehrt }))}
                className={`w-10 h-6 rounded-full transition-colors duration-200 relative ${
                  dialog.ausgefuehrt ? 'bg-primary' : 'bg-border'
                }`}
              >
                <span
                  className={`absolute top-0.5 left-0.5 w-5 h-5 bg-white rounded-full shadow transition-transform duration-200 ${
                    dialog.ausgefuehrt ? 'translate-x-4' : 'translate-x-0'
                  }`}
                />
              </button>
              <Label className="text-sm font-600 cursor-pointer" onClick={() => setDialog((d) => ({ ...d, ausgefuehrt: !d.ausgefuehrt }))}>
                Gewohnheit ausgeführt
              </Label>
            </div>

            {/* Actions */}
            <div className="flex gap-2 pt-2">
              {dialog.mode === 'edit' && dialog.entryId && (
                <Button
                  variant="destructive"
                  size="sm"
                  onClick={() => dialog.entryId && handleDeleteEntry(dialog.entryId)}
                  disabled={deleting === dialog.entryId}
                  className="mr-auto"
                >
                  <Trash2 size={14} />
                  {deleting === dialog.entryId ? 'Löschen…' : 'Löschen'}
                </Button>
              )}
              <Button
                variant="outline"
                onClick={() => setDialog((d) => ({ ...d, open: false }))}
                className="flex-1"
              >
                Abbrechen
              </Button>
              <Button
                onClick={handleSaveDialog}
                disabled={saving || !dialog.habitId}
                className="flex-1"
              >
                {saving ? 'Speichern…' : 'Speichern'}
              </Button>
            </div>
          </div>
        </DialogContent>
      </Dialog>
    </div>
  );
}

