import { useEffect, useState } from 'react';
import { StatCard } from '@/components/StatCard';
import { LivingAppsService } from '@/services/livingAppsService';
import type { GewohnheitenVerwaltung, TaeglicherCheckIn, TaeglicheEintraege } from '@/types/app';

export default function DashboardOverview() {
  const [gewohnheiten_verwaltungCount, setGewohnheitenVerwaltungCount] = useState(0);
  const [taeglicher_check_inCount, setTaeglicherCheckInCount] = useState(0);
  const [taegliche_eintraegeCount, setTaeglicheEintraegeCount] = useState(0);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    async function loadStats() {
      try {
        const [gewohnheiten_verwaltungData, taeglicher_check_inData, taegliche_eintraegeData] = await Promise.all([
          LivingAppsService.getGewohnheitenVerwaltung(),
          LivingAppsService.getTaeglicherCheckIn(),
          LivingAppsService.getTaeglicheEintraege(),
        ]);
        setGewohnheitenVerwaltungCount(gewohnheiten_verwaltungData.length);
        setTaeglicherCheckInCount(taeglicher_check_inData.length);
        setTaeglicheEintraegeCount(taegliche_eintraegeData.length);
      } catch (e) {
        console.error('Failed to load stats:', e);
      } finally {
        setLoading(false);
      }
    }
    loadStats();
  }, []);

  return (
    <div className="space-y-8">
      {/* === HERO SECTION — Customize with gradient, welcome text, key metrics === */}
      <div>
        <h1 className="text-3xl font-bold tracking-tight">Willkommen</h1>
        <p className="text-muted-foreground mt-1">Hier ist eine Übersicht Ihrer Daten.</p>
      </div>

      {/* === KPI CARDS — Customize with icons, colors, descriptions === */}
      <div className="grid grid-cols-2 lg:grid-cols-3 gap-4">
        <StatCard
          title="Gewohnheiten-Verwaltung"
          value={loading ? '...' : gewohnheiten_verwaltungCount}
          description="Gewohnheiten-Verwaltung im System"
        />
        <StatCard
          title="Täglicher Check-in"
          value={loading ? '...' : taeglicher_check_inCount}
          description="Täglicher Check-in im System"
        />
        <StatCard
          title="Tägliche Einträge"
          value={loading ? '...' : taegliche_eintraegeCount}
          description="Tägliche Einträge im System"
        />
      </div>

      {/* === CHARTS / CONTENT — Build your dashboard here === */}
      {/* Ideas: recharts BarChart/LineChart, upcoming items list, recent activity feed */}
    </div>
  );
}

