   245→          <div className="lg:col-span-3 space-y-3">{[1,2,3].map(i => <Skeleton key={i} className="h-24 rounded-2xl" />)}</div>
   246→          <div className="lg:col-span-2 space-y-4"><Skeleton className="h-32 rounded-xl" /><Skeleton className="h-48 rounded-xl" /></div>
   247→        </div>
   248→      </div>
   249→    );
   250→  }
   251→
   252→  if (error && habits.length === 0) {
   253→    return (
   254→      <div className="flex flex-col items-center justify-center py-20 gap-4">
   255→        <div className="flex items-center gap-2 text-destructive"><AlertCircle size={20} /><span className="font-semibold">{error}</span></div>
   256→        <Button variant="outline" onClick={loadData}>Erneut versuchen</Button>
   257→      </div>
   258→    );
   259→  }
   260→
   261→  return (
   262→    <div className="space-y-6 pb-24 lg:pb-0">
   263→      {/* Error banner */}
   264→      {error && habits.length > 0 && (
   265→        <div className="flex items-center gap-3 p-3 bg-destructive/10 text-destructive rounded-xl border border-destructive/20 text-sm">
   266→          <AlertCircle size={16} /><span className="flex-1">{error}</span>
   267→          <button onClick={() => setError(null)}><X size={14} /></button>
   268→        </div>
   269→      )}
   270→
   271→      {/* Header */}
   272→      <div className="flex items-start justify-between">
   273→        <div>
   274→          <p className="text-xs font-semibold text-muted-foreground uppercase tracking-widest mb-1">{getGreeting()}</p>
   275→          <h1 className="text-2xl lg:text-3xl font-extrabold tracking-tight text-foreground capitalize">{todayFormatted}</h1>
   276→        </div>
   277→        <Button onClick={() => handleOpenCreate()} className="hidden lg:flex items-center gap-2 shadow-sm" disabled={saving}>
   278→          <Plus size={16} />Eintrag hinzufügen
   279→        </Button>
   280→      </div>
   281→
   282→      {/* KPI pills */}
   283→      <div className="flex gap-3 overflow-x-auto pb-1 scrollbar-hide">
   284→        {[
   285→          { icon: <Target size={14} />, label: 'Heute', value: `${todayDoneCount} / ${habits.length}`, accent: todayDoneCount === habits.length && habits.length > 0 },
   286→          { icon: <Calendar size={14} />, label: 'Gewohnheiten', value: habits.length, accent: false },
   287→          { icon: <TrendingUp size={14} />, label: 'Einträge gesamt', value: entries.length, accent: false },
   288→        ].map((kpi, i) => (
   289→          <div key={i}
   290→            className={`flex-shrink-0 flex items-center gap-2 px-4 py-2.5 rounded-full border text-sm font-semibold whitespace-nowrap transition-colors ${
   291→              kpi.accent ? 'bg-primary text-primary-foreground border-primary' : 'bg-card text-foreground border-border'
   292→            }`}
   293→            style={{ boxShadow: 'var(--shadow-card)' }}
   294→          >
   295→            <span className={kpi.accent ? 'text-primary-foreground/70' : 'text-muted-foreground'}>{kpi.icon}</span>
   296→            <span>{kpi.label}:</span>
   297→            <span className="font-extrabold">{kpi.value}</span>
   298→          </div>
   299→        ))}
   300→      </div>
   301→
   302→      {/* Main layout */}
   303→      <div className="lg:grid lg:grid-cols-5 lg:gap-6 space-y-6 lg:space-y-0">
   304→
   305→        {/* LEFT — Habit Board */}
   306→        <div className="lg:col-span-3 space-y-3">
   307→          <div className="flex items-center justify-between">
   308→            <h2 className="text-lg font-bold text-foreground">Heute</h2>
   309→            <Badge variant="secondary" className="text-xs font-semibold">{todayDoneCount} / {habits.length} erledigt</Badge>
   310→          </div>
   311→
   312→          {habits.length === 0 ? (
   313→            <div className="flex flex-col items-center justify-center py-16 gap-3 bg-card rounded-2xl border border-border">
   314→              <div className="w-12 h-12 rounded-full bg-accent flex items-center justify-center">
   315→                <Target size={22} className="text-primary" />
   316→              </div>
   317→              <p className="font-semibold text-foreground">Noch keine Gewohnheiten</p>
   318→              <p className="text-sm text-muted-foreground text-center max-w-xs">Erstelle deine erste Gewohnheit unter "Gewohnheiten-Verwaltung"</p>
   319→            </div>
   320→          ) : (
   321→            habits.map((habit, idx) => {
   322→              const entry = todayEntryByHabit.get(habit.record_id);
   323→              const done = entry?.fields.ausgefuehrt === true;
   324→              const timeInvested = entry?.fields.investierte_zeit_minuten ?? 0;
   325→              const timeGoal = habit.fields.zielzeit_minuten ?? 0;
   326→              const percent = timeGoal > 0 ? Math.round((timeInvested / timeGoal) * 100) : done ? 100 : 0;
   327→
   328→              return (
   329→                <div
   330→                  key={habit.record_id}
   331→                  className={`group relative flex items-center gap-4 p-4 rounded-2xl border bg-card transition-all duration-200 hover:shadow-md ${
   332→                    done ? 'border-l-[4px] border-l-primary border-border' : 'border-border'
   333→                  }`}
   334→                  style={{ boxShadow: 'var(--shadow-card)', animationDelay: `${idx * 50}ms` }}
   335→                >
   336→                  {/* Toggle */}
   337→                  <button
   338→                    onClick={() => handleToggleHabit(habit)}
   339→                    disabled={saving}
