   349→                  <div className="flex-1 min-w-0">
   350→                    <p className={`font-bold text-base truncate ${done ? 'text-muted-foreground line-through' : 'text-foreground'}`}>
   351→                      {habit.fields.gewohnheit_name ?? 'Unbenannte Gewohnheit'}
   352→                    </p>
   353→                    {habit.fields.beschreibung && (
   354→                      <p className="text-sm text-muted-foreground truncate mt-0.5">{habit.fields.beschreibung}</p>
