   367→                    </div>
   368→                  </div>
   369→
   370→                  {/* Progress ring */}
   371→                  <div className="flex-shrink-0 flex flex-col items-center gap-0.5">
   372→                    <ProgressRing percent={percent} size={48} stroke={5} done={done} />
   373→                    <span className="text-xs text-muted-foreground font-semibold">{percent}%</span>
   374→                  </div>
