   389→        </div>
   390→
   391→        {/* RIGHT — Analytics */}
   392→        <div className="lg:col-span-2 space-y-4">
   393→          <Button onClick={() => handleOpenCreate()} className="hidden lg:flex w-full items-center gap-2 shadow-sm" disabled={saving}>
