   395→          </Button>
   396→
   397→          {/* 7-day chart */}
   398→          <div className="bg-card rounded-2xl border border-border p-4" style={{ boxShadow: 'var(--shadow-card)' }}>
   399→            <div className="flex items-center gap-2 mb-3">
   400→              <TrendingUp size={15} className="text-primary" />
   401→              <h3 className="font-bold text-sm text-foreground">Letzte 7 Tage</h3>
   402→            </div>
   403→            <div className="h-[140px]">
