   405→                <BarChart data={chartData} barCategoryGap="30%">
   406→                  <XAxis dataKey="label" tick={{ fontSize: 11, fill: 'var(--muted-foreground)', fontFamily: 'Nunito Sans' }} axisLine={false} tickLine={false} />
   407→                  <Tooltip
   408→                    cursor={{ fill: 'var(--muted)', radius: 6 }}
   409→                    contentStyle={{ backgroundColor: 'var(--card)', border: '1px solid var(--border)', borderRadius: '8px', fontSize: '12px', fontFamily: 'Nunito Sans', color: 'var(--foreground)' }}
   410→                    formatter={(value: number) => [`${value} erledigt`, '']}
   411→                  />
   412→                  <Bar dataKey="count" radius={[4, 4, 0, 0]} fill="var(--primary)" />
   413→                </BarChart>
   414→              </ResponsiveContainer>
   415→            </div>
   416→          </div>
   417→
   418→          {/* Recent entries */}
   419→          <div className="bg-card rounded-2xl border border-border p-4" style={{ boxShadow: 'var(--shadow-card)' }}>
   420→            <div className="flex items-center gap-2 mb-3">
   421→              <Calendar size={15} className="text-primary" />
   422→              <h3 className="font-bold text-sm text-foreground">Letzte Einträge</h3>
