   429→                  <div key={entry.record_id} className="flex items-center gap-3 py-2 px-1 rounded-lg hover:bg-muted transition-colors">
   430→                    <div className={`w-2 h-2 rounded-full flex-shrink-0 ${entry.fields.ausgefuehrt ? 'bg-primary' : 'bg-border'}`} />
   431→                    <div className="flex-1 min-w-0">
   432→                      <p className="text-sm font-semibold text-foreground truncate">{entry.habitName}</p>
   433→                      <p className="text-xs text-muted-foreground">
   434→                        {entry.fields.datum ? format(parseISO(entry.fields.datum), 'dd.MM.yyyy', { locale: de }) : '—'}
   435→                        {entry.fields.investierte_zeit_minuten ? ` · ${entry.fields.investierte_zeit_minuten} Min` : ''}
   436→                      </p>
   437→                    </div>
   438→                    <Badge variant={entry.fields.ausgefuehrt ? 'default' : 'secondary'}
   439→                      className={`text-xs flex-shrink-0 ${entry.fields.ausgefuehrt ? 'bg-accent text-accent-foreground' : 'bg-muted text-muted-foreground'}`}>
   440→                      {entry.fields.ausgefuehrt ? '✓' : '—'}
   441→                    </Badge>
   442→                  </div>
   443→                ))}
   444→              </div>
   445→            )}
   446→          </div>
   447→        </div>
   448→      </div>
   449→
   450→      {/* Mobile FAB */}
   451→      <button
   452→        onClick={() => handleOpenCreate()}
   453→        disabled={saving}
   454→        className="lg:hidden fixed bottom-6 right-6 z-50 flex items-center gap-2 bg-primary text-primary-foreground px-4 py-3.5 rounded-full font-bold text-sm active:scale-95 transition-all"
   455→        style={{ boxShadow: '0 8px 24px -4px oklch(0.55 0.10 155 / 0.4)' }}
   456→      >
   457→        <Plus size={18} />Eintrag
   458→      </button>
   459→
   460→      {/* Dialog */}
   461→      <Dialog open={dialog.open} onOpenChange={(open) => setDialog((d) => ({ ...d, open }))}>
   462→        <DialogContent className="sm:max-w-md">
   463→          <DialogHeader>
   464→            <DialogTitle className="font-bold">{dialog.mode === 'edit' ? 'Eintrag bearbeiten' : 'Eintrag hinzufügen'}</DialogTitle>
   465→          </DialogHeader>
   466→          <div className="space-y-4 pt-2">
   467→            <div className="space-y-1.5">
   468→              <Label className="text-sm font-semibold">Gewohnheit</Label>
   469→              <Select value={dialog.habitId ?? ''} onValueChange={(v) => setDialog((d) => ({ ...d, habitId: v }))}>
   470→                <SelectTrigger><SelectValue placeholder="Gewohnheit wählen…" /></SelectTrigger>
   471→                <SelectContent>
   472→                  {habits.map((h) => (
   473→                    <SelectItem key={h.record_id} value={h.record_id}>
   474→                      {h.fields.gewohnheit_name ?? 'Unbenannt'}
   475→                    </SelectItem>
   476→                  ))}
   477→                </SelectContent>
   478→              </Select>
   479→            </div>
   480→
   481→            <div className="space-y-1.5">
   482→              <Label className="text-sm font-semibold">Datum</Label>
   483→              <Input type="date" value={dialog.datum} onChange={(e) => setDialog((d) => ({ ...d, datum: e.target.value }))} />
   484→            </div>
   485→
   486→            <div className="space-y-1.5">
   487→              <Label className="text-sm font-semibold">Investierte Zeit (Minuten)</Label>
   488→              <Input type="number" min="0" placeholder="z.B. 30" value={dialog.investierte_zeit_minuten}
   489→                onChange={(e) => setDialog((d) => ({ ...d, investierte_zeit_minuten: e.target.value }))} />
   490→            </div>
   491→
   492→            <div className="flex items-center gap-3">
   493→              <button
   494→                type="button"
   495→                onClick={() => setDialog((d) => ({ ...d, ausgefuehrt: !d.ausgefuehrt }))}
   496→                className={`w-10 h-6 rounded-full relative transition-colors duration-200 ${dialog.ausgefuehrt ? 'bg-primary' : 'bg-border'}`}
   497→              >
   498→                <span className={`absolute top-0.5 left-0.5 w-5 h-5 bg-white rounded-full shadow transition-transform duration-200 ${dialog.ausgefuehrt ? 'translate-x-4' : 'translate-x-0'}`} />
   499→              </button>
   500→              <Label className="text-sm font-semibold cursor-pointer" onClick={() => setDialog((d) => ({ ...d, ausgefuehrt: !d.ausgefuehrt }))}>
   501→                Gewohnheit ausgeführt
   502→              </Label>
   503→            </div>
   504→
   505→            <div className="flex gap-2 pt-2">
   506→              {dialog.mode === 'edit' && dialog.entryId && (
   507→                <Button variant="destructive" size="sm"
   508→                  onClick={() => dialog.entryId && handleDelete(dialog.entryId)}
   509→                  disabled={deleting === dialog.entryId} className="mr-auto gap-1">
   510→                  <Trash2 size={14} />{deleting === dialog.entryId ? 'Löschen…' : 'Löschen'}
   511→                </Button>
   512→              )}
   513→              <Button variant="outline" onClick={() => setDialog((d) => ({ ...d, open: false }))} className="flex-1">Abbrechen</Button>
   514→              <Button onClick={handleSave} disabled={saving || !dialog.habitId} className="flex-1">
   515→                {saving ? 'Speichern…' : 'Speichern'}
